/*selectCategorySelPop*/ SELECT B.STD_CATEG_ID, B.CATEG_NAME, B.CATEG_TYPE, B.CATEG_PATH, (SELECT COUNT(*) FROM PRMTITEM WHERE CATEGORY_NO = B.STD_CATEG_ID) AS CNT FROM ICOMBYCA A, ICOMBYCA B WHERE A.COM_CODE = 'PRMTITEM' AND A.COM_CODE = B.COM_CODE AND B.DEPTH = 1 AND SUBSTR(A.CATEG_SYS_CODE,0,8) = B.CATEG_SYS_CODE
AND A.CATEG_NAME LIKE '%'|| #{param3} ||'%'
ORDER BY B.CATEG_SYS_CODE

/*selectCategorySelPop*/ SELECT B.STD_CATEG_ID, B.CATEG_NAME, B.CATEG_TYPE, B.CATEG_PATH, (SELECT COUNT(*) FROM PRMTITEM WHERE CATEGORY_NO = B.STD_CATEG_ID) AS CNT FROM ICOMBYCA A, ICOMBYCA B WHERE A.COM_CODE = 'PRMTITEM' AND A.COM_CODE = B.COM_CODE AND B.DEPTH = 2 AND A.STD_CATEG_ID = B.STD_CATEG_ID
AND A.CATEG_NAME LIKE '%'|| #{param3} ||'%'
ORDER BY B.CATEG_SYS_CODE

mapper.select:

/*selectSgInfo*/
SELECT DECODE(COUNT(CODE1), 0,'N','Y') DATA_YN
FROM ICOMCOD3
WHERE BUYER = #{param1}
AND TYPE = #{param2}
AND CODE1 = #{param3}
AND CODE2 = #{param4}


/*selectCategInfo*/
SELECT DECODE(COUNT(CODE2), 0,'N','Y') CATE_DATA_YN
FROM ICOMCOD3
WHERE BUYER = #{param1}
AND TYPE = #{param2}
AND CODE2 = #{param3}
AND FLAG = 'Y'


/*selectBuyerSgInfo*/
SELECT DECODE(COUNT(CODE2), 0,'N','Y') CATE_DATA_YN
FROM ICOMCOD3
WHERE BUYER = #{param1}
AND TYPE = #{param2}
AND CODE1 = #{param3}
AND FLAG = 'Y'


/*selectSmartSgInfo*/
SELECT CODE1||'='||CODE2||','||TEXT1 AS CODE
FROM ICOMCOD3
WHERE BUYER = #{param1}
AND TYPE = #{param2}


/*selectSmartSgIdInfo*/
SELECT CODE2 FROM ICOMCOD3				
WHERE BUYER = #{param1}
AND TYPE = #{param2}
GROUP BY CODE2
